/** SOT-23 / TO-220 教学脚位：与 DeviceLibrary meta 一致 1=B/G 2=C/D 3=E/S */
const BJT_PIN_TO_PAD = new Map([
  ['B', '1'], ['BASE', '1'],
  ['C', '2'], ['COLLECTOR', '2'],
  ['E', '3'], ['EMITTER', '3']
]);
const MOS_PIN_TO_PAD = new Map([
  ['G', '1'], ['GATE', '1'],
  ['D', '2'], ['DRAIN', '2'],
  ['S', '3'], ['SOURCE', '3']
]);

function isBjtLib(libDevId) {
  const lib = (libDevId || '').toLowerCase();
  if (lib.includes('2n7000') || lib.includes('2n7002')) return false;
  return lib.includes('2n2222') || lib.includes('2n2907') || lib.includes('bjt') ||
    (lib.startsWith('2n') && !lib.includes('700'));
}
function isMosLib(libDevId) {
  const lib = (libDevId || '').toLowerCase();
  return lib.includes('2n7000') || lib.includes('2n7002') || lib.includes('irf') ||
    lib.includes('mosfet') || (lib.includes('mos') && !lib.includes('cmos'));
}
